SELECT 
	id_atividade_docente,
	"PID",
	"APROVADA",
	"Importado da planilha, caso este item seja composto de várias atividades do mesmo tipo, o docente poderá juntar os comprovantes em um único PDF ou cadastrar um item para cada atividade.",
	"2023-03-30 17:00:00",
	285
FROM atividade_docente WHERE id_pid >= 20;